insert into public.reviews (id, name, rating, comment, booking_reference, published, created_at) values
  (md5('rev-01')::uuid, 'Rosalinda Fuentes', 5, 'Smooth pick-up at the airport and the Car was spotless. Will book again.', 'RC-AADKNU', true, (((public.manila_today() + -1) + time '09:00') at time zone 'Asia/Manila')),
  (md5('rev-02')::uuid, 'Mark Villanueva', 5, 'Reliable for our company trips. Staff always answer quickly.', 'RC-AADTEB', true, (((public.manila_today() + -4) + time '09:00') at time zone 'Asia/Manila')),
  (md5('rev-03')::uuid, 'Camille Rivera', 4, 'Good Car and fair price. The return process took a little long.', 'RC-AAD25S', true, (((public.manila_today() + -7) + time '09:00') at time zone 'Asia/Manila')),
  (md5('rev-04')::uuid, 'Jun Reyes', 5, 'Booking took a few minutes and the price was exactly as shown.', 'RC-AAEAU9', true, (((public.manila_today() + -10) + time '09:00') at time zone 'Asia/Manila')),
  (md5('rev-05')::uuid, 'Trisha Valdez', 3, 'The Car was fine but I waited about 30 minutes at pick-up.', 'RC-AAEJLQ', false, (((public.manila_today() + -13) + time '09:00') at time zone 'Asia/Manila')),
  (md5('rev-06')::uuid, 'Gerald Uy', 2, 'The van had a warning light on. It was sorted, but I was worried.', 'RC-AAESB7', false, (((public.manila_today() + -16) + time '09:00') at time zone 'Asia/Manila')),
  (md5('rev-07')::uuid, 'Hazel Ocampo', 4, 'Friendly driver contact and easy directions to the meeting point.', 'RC-AAEZ3N', false, (((public.manila_today() + -19) + time '09:00') at time zone 'Asia/Manila'));
